641: 	lmRemoteTime, errParsingRemoteTime := time.Parse(http.TimeFormat, lmRemote)
642: 	if errParsingCachedTime != nil && errParsingRemoteTime != nil {
643: 		// both time strings are failed to parse, so compare them as strings
644: 		return lmCached == lmRemote, lmCached, lmRemote, nil
645: 	} else if errParsingCachedTime == nil && errParsingRemoteTime == nil {
646: 		// both time strings are successfully parsed, so compare them as times
647: 		return lmRemoteTime.Equal(lmCachedTime), lmCached, lmRemote, nil
648: 	}
649: 	// ignore parsing errors for either time string and assume they are different
650: 	return false, lmCached, lmRemote, nil
